import React, { useEffect, useState } from "react";

function Facilities() {
  const [facilities, setFacilities] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://localhost:8081/facilities")
      .then((res) => res.json())
      .then((data) => {
        setFacilities(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching facilities:", err);
        setLoading(false);
      });
  }, []);

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h1 style={styles.title}>Facilities</h1>

        {loading ? (
          <p style={styles.message}>Loading facilities...</p>
        ) : facilities.length === 0 ? (
          <p style={styles.message}>No facilities found.</p>
        ) : (
          <table style={styles.table}>
            <thead>
              <tr>
                <th style={styles.th}>Name</th>
                <th style={styles.th}>Address</th>
                <th style={styles.th}>City</th>
                <th style={styles.th}>State</th>
                <th style={styles.th}>Zip Code</th>
                <th style={styles.th}>Slots</th>
                <th style={styles.th}>Contact</th>
              </tr>
            </thead>
            <tbody>
              {facilities.map((facility) => (
                <tr
                  key={facility.facilityId}
                  style={styles.tr}
                  onMouseEnter={(e) =>
                    (e.currentTarget.style.backgroundColor =
                      "rgba(255,255,255,0.05)")
                  }
                  onMouseLeave={(e) =>
                    (e.currentTarget.style.backgroundColor = "transparent")
                  }
                >
                  <td style={styles.td}>{facility.facilityName}</td>
                  <td style={styles.td}>{facility.address}</td>
                  <td style={styles.td}>{facility.city}</td>
                  <td style={styles.td}>{facility.state}</td>
                  <td style={styles.td}>{facility.zipCode}</td>
                  <td style={styles.td}>{facility.totalSlots}</td>
                  <td style={styles.td}>{facility.contactInfo || "-"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

const styles = {
 page: {
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  minHeight: "100vh",
  padding: "20px",
  backgroundColor: "#002b36", // fallback
  backgroundImage: `
    linear-gradient(135deg, #002b36, #005f73), 
    radial-gradient(rgba(255, 255, 255, 0.15) 1px, transparent 1px)
  `,
  backgroundSize: "cover, 20px 20px",
  backgroundBlendMode: "overlay",
},

  card: {
    background: "rgba(255, 255, 255, 0.08)",
    backdropFilter: "blur(12px)",
    padding: "25px",
    borderRadius: "12px",
    boxShadow: "0 4px 25px rgba(0,0,0,0.4)",
    width: "95%",
    maxWidth: "1000px",
    color: "#fff",
  },
  title: {
    marginBottom: "20px",
    fontSize: "28px",
    fontWeight: "700",
    textAlign: "center",
    color: "#ffffff",
    letterSpacing: "1px",
  },
  message: {
    textAlign: "center",
    fontSize: "16px",
    color: "#ddd",
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
  },
  th: {
    padding: "12px",
    textAlign: "left",
    borderBottom: "2px solid rgba(255,255,255,0.2)",
    color: "#d9c4ff",
    fontWeight: "600",
    fontSize: "14px",
    letterSpacing: "0.5px",
  },
  tr: {
    transition: "background 0.2s ease",
  },
  td: {
    padding: "10px",
    borderBottom: "1px solid rgba(255,255,255,0.1)",
    fontSize: "14px",
    color: "#f5f5f5",
  },
};

export default Facilities;
